// Package models holds the route domain model shared by all packages.
package models

import (
	"fmt"
	"sync/atomic"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

// Default rate limit values applied when a route omits them: 2 Mbit/s in
// each direction and a 64 KiB burst.
const (
	DefaultBytesPerSecond int64 = 2_000_000 / 8
	DefaultBurstBytes     int64 = 64 * 1024
)

// RateLimits caps the bandwidth of a single route in each direction.
type RateLimits struct {
	UploadBytesPerSecond   int64
	DownloadBytesPerSecond int64
	BurstBytes             int64
}

// Rate returns the bandwidth cap for the given traffic direction.
func (l RateLimits) Rate(direction types.Direction) (int64, error) {
	switch direction {
	case types.DirectionUpload:
		return l.UploadBytesPerSecond, nil
	case types.DirectionDownload:
		return l.DownloadBytesPerSecond, nil
	default:
		return 0, fmt.Errorf("unknown traffic direction %q", direction)
	}
}

// Route is a virtual proxy route: clients select it by ID and egress through
// the MikroTik SOCKS5 proxy at SOCKS5Address.
type Route struct {
	ID            string
	SOCKS5Address string
	Limits        *atomic.Pointer[RateLimits]
}

// RouteRef identifies a route version whose idle connections must be dropped.
type RouteRef struct {
	ID            string
	SOCKS5Address string
}

// RouteEntry couples a route with its administrative state.
type RouteEntry struct {
	Route   Route
	Enabled bool
}

// RouteTable is an immutable registry state once published.
type RouteTable struct {
	Entries map[string]*RouteEntry
}

// RouteChanges describes the side effects required after a table swap.
type RouteChanges struct {
	CloseIdle []RouteRef
}
