package httpproxy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"strconv"
	"strings"
	"syscall"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

const (
	modeHTTP                  = "http"
	modeCONNECT               = "connect"
	unknownRoute              = "unknown"
	outcomeClosed             = "closed"
	outcomeStreamFailure      = "stream_failure"
	outcomeThrottleFailure    = "throttle_failure"
	outcomeDestinationFailure = "destination_failure"
)

var errThrottle = errors.New("bandwidth throttle")

type requestHandler struct {
	routes      routeRegistry
	credentials credentials
	limiter     limiter
	connector   connector
	tunnels     *tunnelSet
}

func newRequestHandler(dependencies Dependencies, tunnels *tunnelSet) *requestHandler {
	return &requestHandler{
		routes:      dependencies.Routes,
		credentials: dependencies.Credentials,
		limiter:     dependencies.Limiter,
		connector:   dependencies.Connector,
		tunnels:     tunnels,
	}
}

func (h *requestHandler) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	if request.ProtoMajor != 1 || request.ProtoMinor != 1 {
		metrics.RecordOutcome(request.Context(), unknownRoute, requestMode(request), "unsupported_protocol")
		http.Error(writer, "HTTP/1.1 required", http.StatusHTTPVersionNotSupported)
		return
	}

	routeID, authenticated := h.credentials.Authenticate(request.Header.Get("Proxy-Authorization"))
	if !authenticated {
		h.rejectAuthentication(writer, request, unknownRoute)
		return
	}

	route, exists := h.routes.Lookup(routeID)
	if !exists {
		h.rejectAuthentication(writer, request, unknownRoute)
		return
	}

	if request.Method == http.MethodConnect {
		h.serveConnect(writer, request, route)
		return
	}

	h.serveHTTP(writer, request, route)
}

func (h *requestHandler) serveConnect(writer http.ResponseWriter, request *http.Request, route *models.Route) {
	if err := validateDestination(request.Host); err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "invalid_target")
		http.Error(writer, "bad gateway", http.StatusBadGateway)
		return
	}

	upstream, err := h.connector.Dial(request.Context(), route, request.Host)
	if err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, outcomeDestinationFailure)
		http.Error(writer, "bad gateway", http.StatusBadGateway)
		return
	}

	hijacker, ok := writer.(http.Hijacker)
	if !ok {
		_ = upstream.Close()
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "hijack_unsupported")
		http.Error(writer, "proxy tunneling unavailable", http.StatusInternalServerError)
		return
	}

	client, buffered, err := hijacker.Hijack()
	if err != nil {
		_ = upstream.Close()
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "hijack_failure")
		return
	}

	active := &tunnel{client: client, upstream: upstream}
	if !h.tunnels.add(active) {
		active.close()
		return
	}
	defer func() {
		active.close()
		h.tunnels.remove(active)
	}()

	if _, err = buffered.WriteString("HTTP/1.1 200 Connection Established\r\n\r\n"); err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "client_failure")
		return
	}
	if err = buffered.Flush(); err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "client_failure")

