import (
	"sync"
	"sync/atomic"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
)

// Registry holds the atomically swappable active route table.
type Registry struct {
	updateMu sync.Mutex
	current  atomic.Pointer[models.RouteTable]
}

// New creates a Registry seeded with the initial route table.
func New(initial *models.RouteTable) *Registry {
	registry := &Registry{}
	registry.current.Store(initial)

	return registry
}

// Lookup returns the enabled route with the given ID.
func (r *Registry) Lookup(id string) (*models.Route, bool) {
	value, ok := r.current.Load().Entries[id]
	if !ok || !value.Enabled {
		return nil, false
	}

	return &value.Route, true
}

// Apply swaps the active table, preserving live limit pointers so in-flight
// traffic picks up new limits, and reports which routes need idle cleanup.
func (r *Registry) Apply(table *models.RouteTable) models.RouteChanges {
	r.updateMu.Lock()
	defer r.updateMu.Unlock()

	previous := r.current.Load()
	for id, entry := range table.Entries {
		if old, ok := previous.Entries[id]; ok {
			limits := entry.Route.Limits.Load()
			old.Route.Limits.Store(limits)
			entry.Route.Limits = old.Route.Limits
		}
	}

	changes := diff(previous, table)
	r.current.Store(table)

	return changes
}

func diff(previous, next *models.RouteTable) models.RouteChanges {
	if previous == nil {
		return models.RouteChanges{}
	}

	changes := models.RouteChanges{}
	for id, old := range previous.Entries {
		replacement, exists := next.Entries[id]
		if !exists || !replacement.Enabled || replacement.Route.SOCKS5Address != old.Route.SOCKS5Address {
			changes.CloseIdle = append(changes.CloseIdle, models.RouteRef{
				ID:            old.Route.ID,
				SOCKS5Address: old.Route.SOCKS5Address,
			})
		}
	}

	return changes
}

